import assert from 'node:assert/strict'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { pathToFileURL } from 'node:url'
import { resolve } from 'node:path'

// Bootstrap receipt is generated by the isolated verifier, never a personal
// Codex/OpenCodex auth file. It contains only the current DSH Web bootstrap URL.
const bootstrap = process.env.AEZY_OBSERVABILITY_BOOTSTRAP ?? '/tmp/aezy-observability-bootstrap.json'
const { url } = JSON.parse(await readFile(bootstrap, 'utf8'))
const modulePath = resolve(process.env.AEZY_PLAYWRIGHT_MODULE ?? '.local/aezy-model-fixes-XqAlLV/browser/node_modules/playwright/index.mjs')
const { chromium } = await import(pathToFileURL(modulePath).href)
const browser = await chromium.launch({ executablePath: resolve(process.env.AEZY_CHROMIUM ?? '.local/aezy-model-fixes-XqAlLV/browsers/chromium_headless_shell-1187/chrome-linux/headless_shell'), headless: true, args: ['--no-sandbox'] })
const directory = process.env.AEZY_OBSERVABILITY_RECEIPTS ?? '/tmp/aezy-observability-proof'
const checks = []
let diagnosticPage
try {
  await mkdir(directory, { recursive: true })
  const page = await browser.newPage({ viewport: { width: 1500, height: 1000 }, colorScheme: 'dark' })
  diagnosticPage = page
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  // Apply to every document, including reloads in the navigation proof.
  await page.addInitScript(async data => {
    const font = new FontFace('QA Sans', `url(data:font/ttf;base64,${data})`)
    document.fonts.add(await font.load())
    const style = document.createElement('style')
    style.textContent = '*{font-family:"QA Sans",sans-serif!important}'
    document.documentElement.append(style)
  }, (await readFile('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf')).toString('base64'))
  await page.goto(url, { waitUntil: 'networkidle' })
  const notice = page.getByRole('dialog').filter({ hasText: 'Internal Testing Notice' })
  if (await notice.count()) await notice.getByRole('button', { name: 'Continue', exact: true }).click()
  const nav = page.locator('[data-aezy-observability-nav]'), panel = page.locator('[data-aezy-observability-page]')
  assert.ok((await nav.boundingBox()).y < (await page.getByRole('button', { name: 'Settings', exact: true }).boundingBox()).y)
  await nav.getByRole('button', { name: 'Logs & Debug', exact: true }).click()
  await panel.getByRole('heading', { name: 'Logs & Debug', exact: true }).waitFor()
  await panel.getByRole('radio', { name: 'Codex gateway', exact: true }).waitFor()
  assert.equal(await panel.getByRole('radio', { name: /Claude|Grok/ }).count(), 0)
  await panel.getByRole('radio', { name: 'DSH native', exact: true }).click()
  await panel.getByRole('button', { name: /^Details:/ }).first().waitFor()
  assert.ok((await panel.locator('tbody').innerText()).includes('DSH native'))
  await panel.getByRole('radio', { name: 'All', exact: true }).click()
  await panel.getByRole('checkbox', { name: 'Auto-refresh' }).uncheck()
  await panel.getByRole('button', { name: /^Details:/ }).first().click()
  const dialog = page.getByRole('dialog')
  await dialog.waitFor()
  assert.ok((await dialog.innerText()).includes('Accounting unit'))
  await page.context().grantPermissions(['clipboard-read', 'clipboard-write'])
  await dialog.getByRole('button', { name: 'Copy request ID', exact: true }).click()
  assert.ok((await page.evaluate(() => navigator.clipboard.readText())).length > 0)
  checks.push('copy-request-id')
  await page.screenshot({ path: `${directory}/details.png` })
  const filter = dialog.getByRole('button', { name: 'Filter logs', exact: true })
  if (await filter.count()) { await filter.click(); assert.notEqual(await panel.getByRole('searchbox', { name: 'Conversation', exact: true }).inputValue(), '') }
  else { await page.keyboard.press('Escape'); await panel.getByRole('searchbox', { name: 'Conversation', exact: true }).fill('no-matching-conversation') }
  await panel.getByRole('searchbox', { name: 'Conversation', exact: true }).fill('no-matching-conversation')
  await panel.getByText('No requests yet', { exact: false }).waitFor()
  await panel.getByRole('button', { name: /Clear/ }).click()
  await panel.getByRole('checkbox', { name: 'Auto-refresh' }).check()
  await page.screenshot({ path: `${directory}/logs-dark.png` })
  checks.push('sidebar-above-settings', 'dynamic-surfaces', 'native-filter', 'details-dialog', 'conversation-filter-clear', 'auto-refresh')

  await panel.getByRole('tab', { name: 'Debug', exact: true }).click()
  assert.equal(new URL(page.url()).searchParams.get('aezyTab'), 'debug')
  await panel.getByRole('button', { name: 'Clear runtime overrides', exact: true }).click()
  await panel.getByText('Debug logging is off', { exact: true }).waitFor()
  const providerToggle = panel.getByRole('button', { name: 'Provider debug', exact: true })
  await providerToggle.click()
  await page.waitForFunction(() => document.querySelector('button[aria-label="Provider debug"]')?.getAttribute('aria-pressed') === 'true')
  await panel.getByRole('button', { name: 'Usage extraction', exact: true }).click()
  await panel.getByRole('button', { name: 'Request composition', exact: true }).click()
  await panel.getByRole('button', { name: 'Inbound metadata', exact: true }).click()
  await panel.getByRole('button', { name: 'Composition', exact: true }).click()
  await panel.getByRole('checkbox', { name: 'Follow', exact: true }).uncheck()
  await panel.getByRole('button', { name: 'Refresh', exact: true }).click()
  await panel.getByRole('checkbox', { name: 'Follow', exact: true }).check()
  await page.screenshot({ path: `${directory}/debug-dark.png` })
  checks.push('debug-reset', 'four-opt-in-toggles', 'stream-switch', 'manual-refresh', 'follow')
  // A failed mutation is visible and must not optimistically flip the switch.
  await page.route('**/aezy/observability/api/debug', async route => route.request().method() === 'PUT' ? route.fulfill({ status: 503, body: '{}' }) : route.continue())
  await providerToggle.click()
  await panel.getByText('Debug settings were not saved.', { exact: false }).waitFor()
  assert.equal(await providerToggle.getAttribute('aria-pressed'), 'true')
  await page.unroute('**/aezy/observability/api/debug')
  await panel.getByRole('button', { name: 'Clear runtime overrides', exact: true }).click()
  checks.push('debug-write-failure-honesty')

  await panel.locator('.aezy-page-tools').getByRole('button', { name: 'Usage', exact: true }).click()
  await panel.getByRole('tab', { name: /^Overview/ }).waitFor()
  await panel.getByRole('button', { name: '7d', exact: true }).click()
  await panel.locator('.daybars').waitFor()
  assert.equal(await panel.locator('.daybar').count(), 7)
  await panel.getByRole('button', { name: 'Available history', exact: true }).click()
  await panel.locator('.heatmap-grid').waitFor()
  await panel.getByRole('button', { name: 'DSH native', exact: true }).click()
  await panel.getByRole('tab', { name: /^Models/ }).click()
  const search = panel.getByRole('textbox', { name: /Search models/ })
  await search.fill('no-such-model')
  assert.equal(await panel.locator('#usage-models-title').locator('..').locator('tbody tr').count(), 0)
  await search.fill('deepseek')
  await panel.getByRole('button', { name: 'All', exact: true }).click()
  await panel.getByRole('tab', { name: /^Overview/ }).click()
  await page.waitForTimeout(300)
  await panel.evaluate(node => { node.scrollTop = 0 })
  await page.screenshot({ path: `${directory}/usage-dark.png` })
  checks.push('usage-seven-day-bars', 'heatmap', 'usage-surface-filter', 'section-navigation', 'model-search', 'cost-coverage')
  assert.equal(new URL(page.url()).searchParams.get('aezyView'), 'usage')
  await page.reload({ waitUntil: 'networkidle' })
  await panel.getByRole('tab', { name: /^Overview/ }).waitFor()
  await page.goBack()
  await panel.getByRole('heading', { name: 'Logs & Debug', exact: true }).waitFor()
  await page.goForward()
  await panel.getByRole('tab', { name: /^Overview/ }).waitFor()
  checks.push('refresh-bookmark', 'browser-back-forward')

  await page.emulateMedia({ colorScheme: 'light' })
  await page.waitForTimeout(200)
  await page.screenshot({ path: `${directory}/usage-light.png` })
  await page.setViewportSize({ width: 420, height: 900 })
  await page.screenshot({ path: `${directory}/usage-narrow.png` })
  assert.ok((await panel.boundingBox()).width <= 420)
  assert.ok(await panel.evaluate(node => node.scrollWidth <= node.clientWidth + 1))
  await panel.getByRole('button', { name: 'Close observability' }).click()
  assert.equal(await panel.count(), 0)
  checks.push('light-dark', 'narrow', 'return-to-session')
  assert.deepEqual(errors, [])
  const receipt = { timestamp: new Date().toISOString(), base: new URL(url).origin, checks, browserErrors: errors }
  await writeFile(`${directory}/browser.json`, `${JSON.stringify(receipt, null, 2)}\n`)
  console.log(JSON.stringify(receipt, null, 2))
} catch(error) {
  await diagnosticPage?.screenshot({path:`${directory}/failure.png`})
  console.log('Failure UI:',(await diagnosticPage?.locator('body').innerText())?.slice(0,2500))
  throw error
} finally { await browser.close() }
